}

input.newString:
upper() {
  printf '%s\n' "${1^^}"
}

reverse() {
  local s=$1 out='' i
  for (( i = ${#s} - 1; i >= 0; i-- )); do
    out+=${s:i:1}
  done
  printf '%s\n' "$out"
}

